data
  title Scale in Context
  desc A handful of firms command a staggering share of global value
  lists
    - label $25.4T
      desc Combined market cap of the top 10 companies
      icon chart bar
    - label 17.8%
      desc Share of global market value held by just 10 firms (0.09% of all companies)
      icon pie chart
    - label 9x Drop
      desc Valuation gap from Rank 1 ($4.82T) to Rank 20 ($554B)
      icon arrow down
    - label 10,796
      desc Total companies tracked globally, worth $142.9T combined
      icon globe
theme
  palette #3b82f6 #06b6d4 #10b981 #f59e0b`;

    // Initialize and render infographics
    const chart1 = new AntVInfographic.Infographic({
      container: '#chart-trillion',
      width: '100%',
      height: '100%',
    });

    const chart2 = new AntVInfographic.Infographic({
