      container: '#chart-sector',
      width: '100%',
      height: '100%',
    });

    const chart4 = new AntVInfographic.Infographic({
      container: '#chart-context',
      width: '100%',
      height: '100%',
    });

    // Render all charts
    chart1.render(syntaxTrillion);
    chart2.render(syntaxCountry);
    chart3.render(syntaxSector);
    chart4.render(syntaxContext);

    // Re-render after fonts load, then signal completion
    document.fonts?.ready.then(() => {
      setTimeout(() => {
        chart1.render(syntaxTrillion);
        chart2.render(syntaxCountry);
        chart3.render(syntaxSector);
        chart4.render(syntaxContext);

        // Wait for render to settle
        setTimeout(() => {
          window.renderingComplete = true;
        }, 2000);
      }, 500);
    }).catch(() => {
      window.renderingComplete = true;
    });

    // Fallback: if fonts.ready doesn't fire within 8s, signal anyway
    setTimeout(() => {
      window.renderingComplete = true;
    }, 8000);
  </script>
