const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
  });

  const page = await browser.newPage();

  // Set viewport wider than poster to avoid clipping
  await page.setViewport({ width: 900, height: 1000 });

  // Load the HTML file
  const htmlPath = path.resolve(__dirname, 'poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle0', timeout: 30000 });

  // Wait for infographic rendering to complete
  try {
    await page.waitForFunction(() => window.renderingComplete === true, { timeout: 15000 });
    console.log('Rendering complete signal received');
  } catch (e) {
    console.log('Rendering signal timeout - proceeding with capture anyway');
  }

  // Extra wait for any final rendering
  await new Promise(resolve => setTimeout(resolve, 2000));

  // Get the poster element and its bounding box
  const poster = await page.$('.poster');
  const bbox = await poster.boundingBox();

  console.log(`Poster dimensions: ${bbox.width}x${bbox.height}`);

  // Capture the poster as PNG with proper scaling
  await poster.screenshot({
    path: path.resolve(__dirname, 'output/final_poster.png'),
    type: 'png',
    clip: {
      x: bbox.x,
      y: bbox.y,
      width: bbox.width,
      height: bbox.height
    }
  });

  console.log('Poster saved to /app/output/final_poster.png');
  await browser.close();
})();

