const puppeteer = require('puppeteer');
(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 900, height: 1000, deviceScaleFactor: 2 });
  await page.goto('file:///app/poster.html', { waitUntil: 'networkidle0', timeout: 30000 });
  try {
    await page.waitForFunction(() => window.renderingComplete === true, { timeout: 15000 });
  } catch(e) {}
  await new Promise(r => setTimeout(r, 2000));

  // Check infographic containers
  const info = await page.evaluate(() => {
    const containers = document.querySelectorAll('[id^=chart-]');
    const results = [];
    containers.forEach(c => {
      results.push({
        id: c.id,
        width: c.offsetWidth,
        height: c.offsetHeight,
        childCount: c.children.length,
        hasSVG: c.querySelector('svg') !== null,
        svgSize: c.querySelector('svg') ? c.querySelector('svg').getBoundingClientRect() : null
      });
    });
    return results;
  });
  console.log(JSON.stringify(info, null, 2));
  await browser.close();
})();
