const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
  });

  const page = await browser.newPage();

  // 2x device scale factor for crisp output
  await page.setViewport({ width: 900, height: 1000, deviceScaleFactor: 2 });

  const htmlPath = path.resolve(__dirname, 'poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle0', timeout: 30000 });

  // Wait for fonts to load
  await page.waitForFunction(() => document.fonts?.ready.then(() => true), { timeout: 10000 }).catch(() => {});
  await new Promise(resolve => setTimeout(resolve, 1500));

  const poster = await page.$('.poster');
  const bbox = await poster.boundingBox();
  console.log(`Poster: ${bbox.width}x${bbox.height}`);

  await poster.screenshot({
    path: path.resolve(__dirname, 'output/final_poster.png'),
    type: 'png',
    clip: {
      x: bbox.x,
      y: bbox.y,
      width: bbox.width,
      height: bbox.height
    }
  });

  console.log('Done - /app/output/final_poster.png');
  await browser.close();
})();

